import { platformContent, type PlatformId } from '../game/content/social';

const formerNames = /\b(?:photogram|videowave|streamline|lifelink)\b/gi;
const legacyCreation = /\b(I created)\s+(?:a|an)\s+(photogram|videowave|streamline|lifelink)\s+profile(?=\s*(?::|[.!?](?:\s|$)|$))/gi;
const identifierEdge = /[@\w/.-]/;

/** Read-only compatibility for saved prose; never use this to rewrite a save. */
export function displayPlatformNames(value: string): string {
  // This exact journal sentence was generated by the older account-creation
  // flow. Fix its noun/article together, without rewriting arbitrary profiles,
  // handles, URLs, or any persisted prose.
  value = value.replace(legacyCreation, (_sentence, lead: string, former: string) => {
    const platform = former.toLowerCase() as PlatformId;
    const content = platformContent[platform];
    const article = platform === 'photogram' || platform === 'lifelink' ? 'an' : 'a';
    return lead + ' ' + article + ' ' + content.name + ' ' + content.accountType;
  });
  return value.replace(formerNames, (word: string, offset: number) => {
    const before = value[offset - 1] ?? '', after = value.slice(offset + word.length);
    const prefix = value.slice(0, offset);
    const token = (prefix.match(/\S*$/)?.[0] ?? '') + word + (after.match(/^\S*/)?.[0] ?? '');
    // Handles, URLs, dotted names and stored IDs retain their literal spelling.
    if (token.includes('@') || identifierEdge.test(before) || /^[\w/@-]|^\.[A-Za-z0-9]/.test(after)
      || /\b(?:[A-Za-z][A-Za-z0-9+.-]*:|www\.)\S*$/.test(prefix)
      || /\b(?:[A-Za-z0-9-]+\.)+[A-Za-z]{2,}[/?#]\S*$/.test(prefix)) return word;
    const platform = word.toLowerCase() as PlatformId;
    if (platform === 'streamline') {
      // The ordinary verb has many valid complements, including production,
      // editing and payments. Require the known platform contexts from saved
      // copy rather than guessing from capitalization or a list of objects.
      const contextual = /\b(?:on|via|from|using|my|your|our|a|an|the)\s+$/i.test(prefix);
      const listItem = /(?:^|[/|,·])\s*$/.test(prefix) && /^\s*(?:$|[/|,·])/.test(after);
      const labelled = /:\s*$/.test(prefix) && /^[.!?]?\s*$/.test(after) || /^\s*[:·]/.test(after);
      if (value.trim() !== word && !contextual && !listItem && !labelled) return word;
    }
    return platformContent[platform].name;
  });
}
